interface Student {
    id: number,
    name: string,
    age: number,
    sex: string,
    photo: string
}

function Person(student: Student) {
    return (
        <div className="student">
            <div className="avatar">
                <img src={student.photo} alt="" />
            </div>
            <h1>{student.name}</h1>
            <h2>编号</h2>
            <p>性别：{student.sex} 年龄：{student.age}</p>
        </div>
    )
}

export default Person;
